"""Generated bytes and fake HDF5 handles only; no native library import."""
import hashlib
import io
import json
import types
import sys
import os
from pathlib import Path
import tempfile
import unittest
from unittest.mock import patch

import regenerate_metadata as regen


class FakeFile:
    def __init__(self, stream, calls, mutate=False):
        self.stream,self.calls,self.mutate=stream,calls,mutate
    def __enter__(self):
        self.calls.append(('native-open',self.stream.tell()))
        return object()
    def __exit__(self,*args):
        if self.mutate:
            os.utime(self.stream.fileno(),ns=(1,1))


class FakeH5:
    def __init__(self, calls, mutate=False): self.calls,self.mutate=calls,mutate
    def File(self, stream, mode, **kwargs):
        if mode!='r' or kwargs!={'rdcc_nbytes':1048576}: raise AssertionError('Unexpected reader profile')
        return FakeFile(stream,self.calls,self.mutate)


def descriptor(body):
    return {'basename':'synthetic.nwb','asset_id':'synthetic-asset','source_subject_id':'synthetic-animal',
            'source_path':'synthetic/synthetic.nwb','bytes':len(body),
            'sha256':hashlib.sha256(body).hexdigest(),'expected_rows':2}


class MetadataRegenerationTests(unittest.TestCase):
    def fixture(self, wrong=False, symlink=False):
        tmp=tempfile.TemporaryDirectory(dir=Path(__file__).parent)
        root=Path(tmp.name);body=b'GENERATED NOT HDF5\n';path=root/'synthetic.nwb'
        if symlink:
            (root/'target').write_bytes(body);path.symlink_to(root/'target')
        else:path.write_bytes(body)
        planned=descriptor(body)
        if wrong:planned['sha256']='0'*64
        return tmp,root,planned

    def test_hash_precedes_same_descriptor_native_open_and_float_timing(self):
        tmp,root,item=self.fixture();calls=[]
        try:
            fd=os.open(root,os.O_RDONLY|os.O_DIRECTORY)
            with patch.object(regen.metadata_source,'read_metadata',return_value={'generated':True}),\
                 patch.object(regen.runtime_io,'read_trial_columns',return_value=([9,15],[1,2],[1.01,2.01])):
                asset,timing=regen.inspect_asset(fd,item,{}, {},FakeH5(calls))
            self.assertEqual(calls,[('native-open',0)])
            self.assertEqual(asset,{'generated':True})
            self.assertEqual([r['source_trial_id'] for r in timing['rows']],[9,15])
            self.assertIs(type(timing['rows'][0]['start_time']),float)
            self.assertFalse(timing['continuous_support_verified'])
            self.assertEqual(timing['full_file_hash_bytes'],item['bytes'])
        finally:
            os.close(fd);tmp.cleanup()

    def test_hash_mismatch_and_symlink_refuse_before_native_open(self):
        for kw in ({'wrong':True},{'symlink':True}):
            tmp,root,item=self.fixture(**kw);calls=[]
            try:
                fd=os.open(root,os.O_RDONLY|os.O_DIRECTORY)
                with self.assertRaises((ValueError,OSError)):
                    regen.inspect_asset(fd,item,{}, {},FakeH5(calls))
                self.assertEqual(calls,[])
            finally:os.close(fd);tmp.cleanup()

    def test_mutation_during_metadata_decode_refuses(self):
        tmp,root,item=self.fixture();calls=[]
        try:
            fd=os.open(root,os.O_RDONLY|os.O_DIRECTORY)
            with patch.object(regen.metadata_source,'read_metadata',return_value={}),\
                 patch.object(regen.runtime_io,'read_trial_columns',return_value=([9,15],[1,2],[1.01,2.01])):
                with self.assertRaises(ValueError):
                    regen.inspect_asset(fd,item,{}, {},FakeH5(calls,True))
        finally:os.close(fd);tmp.cleanup()

    def test_partial_or_wrong_cases_never_receive_complete_documents(self):
        contract={'DECLARED_SUPPORT.json':{},'COHORT_BINDING.json':{}}
        with patch.object(regen.prepare_counts,'join_inputs',return_value=([],{},[])):
            with self.assertRaises(ValueError):regen.documents([],[],contract)
        with patch.object(regen.prepare_counts,'join_inputs',return_value=([],{},[{}]*9867)):
            with self.assertRaises(ValueError):regen.documents([],[],contract)

    def test_case_file_newline_and_float_representation_are_part_of_commitment(self):
        integer=regen.canonical([{'start':1}]);floating=regen.canonical([{'start':1.0}])
        self.assertNotEqual(integer,floating)
        self.assertTrue(floating.endswith(b'\n'))
        self.assertNotEqual(hashlib.sha256(floating).digest(),hashlib.sha256(floating[:-1]).digest())

    def test_each_changed_contract_refuses_before_runtime_or_source_access(self):
        for changed in regen.CONTRACT_PINS:
            with tempfile.TemporaryDirectory(dir=Path(__file__).parent) as tmp:
                root=Path(tmp);(root/'contract').mkdir();(root/'preparation').mkdir();(root/'raw').mkdir()
                pins={}
                for name in regen.CONTRACT_PINS:
                    body=b'{"generated":true}\n';(root/'contract'/name).write_bytes(body)
                    pins[name]=hashlib.sha256(body).hexdigest()
                pins[changed]='0'*64
                with patch.object(regen,'HERE',root/'preparation'),\
                     patch.dict(regen.CONTRACT_PINS,pins,clear=True),\
                     patch.object(regen.runtime_io,'initialize_runtime') as native,\
                     patch.object(regen,'inspect_asset') as inspect,\
                     patch.object(regen,'write_new') as write:
                    with self.assertRaises(ValueError):
                        regen.main(['--execute-authenticated-metadata-regeneration',
                                    '--raw-root',str(root/'raw'),'--output',str(root/'out')])
                    native.assert_not_called();inspect.assert_not_called();write.assert_not_called()
                    self.assertFalse((root/'out').exists())

    def test_document_commitment_failure_prevents_output_directory(self):
        with tempfile.TemporaryDirectory(dir=Path(__file__).parent) as tmp:
            root=Path(tmp);(root/'raw').mkdir()
            contract={'SOURCES.json':{'assets':[]},'DECLARED_SUPPORT.json':{'assets':[]}}
            with patch.object(regen,'read_contract',return_value=(contract,[])),\
                 patch.object(regen.runtime_io,'initialize_runtime',return_value=(object(),regen.RUNTIME)),\
                 patch.object(regen,'documents',side_effect=ValueError('synthetic commitment refusal')),\
                 patch.object(regen,'write_new') as write:
                with self.assertRaises(ValueError):
                    regen.main(['--execute-authenticated-metadata-regeneration',
                                '--raw-root',str(root/'raw'),'--output',str(root/'out')])
                write.assert_not_called();self.assertFalse((root/'out').exists())

    def test_late_directory_sync_failure_has_no_success_receipt(self):
        with tempfile.TemporaryDirectory(dir=Path(__file__).parent) as tmp:
            root=Path(tmp);(root/'raw').mkdir();output=root/'out'
            contract={'SOURCES.json':{'assets':[]},'DECLARED_SUPPORT.json':{'assets':[]}}
            factory=types.SimpleNamespace(create_binding=lambda *a,**k:{'generated':True})
            original=os.fsync
            def fail_final_directory(fd):
                if (output/'METADATA_COMPLETE.json').exists() and os.fstat(fd).st_ino==output.stat().st_ino:
                    raise OSError('synthetic late directory failure')
                return original(fd)
            captured=io.StringIO()
            with patch.object(regen,'read_contract',return_value=(contract,[])),\
                 patch.object(regen.runtime_io,'initialize_runtime',return_value=(object(),regen.RUNTIME)),\
                 patch.object(regen,'documents',return_value=({'generated':True},{'generated':True})),\
                 patch.dict(sys.modules,{'bindings':factory}),\
                 patch.object(regen.os,'fsync',side_effect=fail_final_directory),\
                 patch('sys.stdout',captured):
                with self.assertRaises(OSError):
                    regen.main(['--execute-authenticated-metadata-regeneration',
                                '--raw-root',str(root/'raw'),'--output',str(output)])
            self.assertEqual(captured.getvalue(),'')
            candidate=json.loads((output/'METADATA_COMPLETE.json').read_text())
            self.assertTrue(candidate['requires_clean_supervised_completion'])

    def test_output_is_exclusive_and_bound_without_clipping(self):
        with tempfile.TemporaryDirectory(dir=Path(__file__).parent) as tmp:
            path=Path(tmp)/'synthetic.json'
            record={'generated':True,'number':10**308+1}
            with self.assertRaises(ValueError):regen.write_new(path,record,32)
            self.assertFalse(path.exists())
            pin=regen.write_new(path,record,1024)
            self.assertEqual(pin['bytes'],len(regen.canonical(record)))
            with self.assertRaises(FileExistsError):regen.write_new(path,record,1024)
            self.assertEqual(path.stat().st_mode&0o777,0o600)


if __name__=='__main__':unittest.main()
